<div class="tabs"><a class="<?= $st === '' ? 'on' : '' ?>" href="/admin/ats/jobs">All</a><?php foreach (['pending' => 'To review', 'published' => 'Published', 'draft' => 'Drafts', 'closed' => 'Closed', 'rejected' => 'Rejected'] as $k => $v): ?><a class="<?= $st === $k ? 'on' : '' ?>" href="<?= e(url('/admin/ats/jobs', ['status' => $k])) ?>"><?= $v ?><?= !empty($counts[$k]) ? ' (' . (int) $counts[$k] . ')' : '' ?></a><?php endforeach; ?></div>
<div class="toolbar"><span class="grow"></span><a class="btn btn-primary btn-sm" href="/admin/ats/job/new"><?= icon('plus', 15) ?> New vacancy</a></div>
<div class="table-wrap"><table class="t"><thead><tr><th>Vacancy</th><th>Status</th><th class="num">Applicants</th><th class="num">Views</th><th>Deadline</th><th></th></tr></thead><tbody>
<?php foreach ($items as $j): ?><tr><td><a href="/admin/ats/job/<?= (int) $j['id'] ?>"><strong><?= e($j['title']) ?></strong></a> <?= $j['featured'] ? badge('Featured', 'dark') : '' ?><div class="muted xs"><?= e($j['organisation']) ?> · <?= e($j['location']) ?> · <?= $j['source'] === 'employer' ? 'Submitted by employer' : 'Internal' ?></div></td><td><?= badge($j['status'], ['published' => 'green', 'pending' => 'amber', 'rejected' => 'red'][$j['status']] ?? '') ?></td>
<td class="num"><a href="<?= e(url('/admin/ats/applications', ['job' => $j['id']])) ?>"><?= (int) $j['apps'] ?></a><?= $j['fresh'] ? ' <span class="badge amber">' . (int) $j['fresh'] . ' new</span>' : '' ?></td><td class="num"><?= (int) $j['views'] ?></td><td class="small"><?= e(fmt_date($j['deadline'])) ?: '—' ?></td>
<td class="tbl-actions"><a class="rowbtn" href="/admin/ats/job/<?= (int) $j['id'] ?>">Edit</a><a class="rowbtn" href="<?= e(url('/admin/ats', ['job' => $j['id']])) ?>">Pipeline</a>
<?php foreach (($j['status'] === 'pending' ? ['published' => 'Approve', 'rejected' => 'Reject'] : ($j['status'] === 'published' ? ['closed' => 'Close'] : ['published' => 'Publish'])) as $to => $lbl): ?><form method="post" action="/admin/ats/job/<?= (int) $j['id'] ?>/status"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $to ?>"><button class="rowbtn <?= $to === 'rejected' ? 'danger' : '' ?>"><?= $lbl ?></button></form><?php endforeach; ?></td></tr><?php endforeach; ?>
<?php if (!$items): ?><tr><td colspan="6" class="center muted" style="padding:30px">No vacancies here.</td></tr><?php endif; ?></tbody></table></div>
